#!/usr/bin/env python3
import argparse
import json
import re
import subprocess
import sys
import tempfile
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
INDEX_HEADER = (
    "# Index\n\n"
    "Generated by `harness/stamp.py` from the front matter of every entry. Do not edit it by hand.\n\n"
)
VERIFIED_HEADING = "## Verified on"
SECTION_PATTERN = re.compile(r"^## Verified on[ \t]*\n.*?(?=^## |\Z)", re.MULTILINE | re.DOTALL)
RESULT_ARTIFACT_PREFIX = "results-"
NO_RUN_TEXT = "No CI run has been recorded yet. Every statement below is source reading.\n"


class StampError(Exception):
    pass


def split_entry(text):
    if not text.startswith("---\n"):
        raise StampError("entry has no front matter")
    end = text.find("\n---\n", 4)
    if end < 0:
        raise StampError("front matter is not closed")
    return yaml.safe_load(text[4:end]) or {}, text[end + len("\n---\n"):]


def dump_front(front):
    return yaml.safe_dump(front, sort_keys=False, allow_unicode=True, width=1000, default_flow_style=False)


def join_entry(front, body):
    return f"---\n{dump_front(front)}---\n{body}"


def load_results(results_dir):
    results = []
    for path in sorted(Path(results_dir).rglob("*.json")):
        record = json.loads(path.read_text(encoding="utf-8"))
        if {"slug", "tag", "class"} <= set(record):
            results.append(record)
    return results


def verified_item(result):
    if not result.get("run_url"):
        raise StampError(f"{result['slug']} {result['tag']}: a stamp needs a CI run URL; local runs are not stamped")
    return {
        "tag": result["tag"],
        "digest": result["digest"],
        "date": result["timestamp_utc"][:10],
        "observed": result["token"],
        "run": result["run_url"],
    }


def merge_verified(existing, items, tag_order):
    by_tag = {item["tag"]: item for item in existing or []}
    for item in items:
        by_tag[item["tag"]] = item
    position = {tag: index for index, tag in enumerate(tag_order)}
    return sorted(by_tag.values(), key=lambda item: (position.get(item["tag"], len(position)), item["tag"]))


def fully_verified(verified, expectations, pinned):
    current = {
        item["tag"]
        for item in verified
        if item["tag"] in pinned and item["digest"] == pinned[item["tag"]]["digest"]
        and expectations.get(item["tag"]) == item["observed"]
    }
    return bool(expectations) and set(expectations) <= current


def verified_section(verified):
    if not verified:
        return f"{VERIFIED_HEADING}\n\n{NO_RUN_TEXT}\n"
    lines = [VERIFIED_HEADING, "", "| Tag | Observed | Date | Digest | Run |", "| --- | --- | --- | --- | --- |"]
    for item in verified:
        lines.append(
            f"| {item['tag']} | `{item['observed']}` | {item['date']} | `{item['digest'][:19]}` | [run]({item['run']}) |"
        )
    return "\n".join(lines) + "\n\n"


def replace_verified_section(body, verified):
    if not SECTION_PATTERN.search(body):
        raise StampError("entry has no Verified on section")
    return SECTION_PATTERN.sub(lambda _: verified_section(verified), body, count=1)


def stamp_entry(entry_dir, results, images):
    readme = entry_dir / "README.md"
    front, body = split_entry(readme.read_text(encoding="utf-8"))
    expectations = json.loads((entry_dir / "expect.json").read_text(encoding="utf-8"))
    items = [verified_item(result) for result in results]
    verified = merge_verified(front.get("verified_on"), items, list(images["tags"]))
    front["verified_on"] = verified
    if fully_verified(verified, expectations, images["tags"]):
        front["confidence"] = "reproduced"
    readme.write_text(join_entry(front, replace_verified_section(body, verified)), encoding="utf-8")
    return front


def entry_fronts(entries_dir):
    fronts = []
    if not entries_dir.is_dir():
        return fronts
    for readme in sorted(entries_dir.glob("*/README.md")):
        front, _ = split_entry(readme.read_text(encoding="utf-8"))
        fronts.append(front)
    return sorted(fronts, key=lambda front: int(str(front.get("id", "E0"))[1:] or 0))


def last_verified(front):
    dates = [str(item["date"]) for item in front.get("verified_on") or []]
    return max(dates) if dates else "not yet"


def render_index(fronts):
    if not fronts:
        return INDEX_HEADER + "No entries yet.\n"
    lines = [
        "| Id | Entry | Kind | Status | Affected | Fixed in | Confidence | Last verified |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for front in fronts:
        lines.append(
            "| {id} | [{title}](entries/{slug}/README.md) | {kind} | {status} | {affected} | {fixed} | {confidence} | {verified} |".format(
                id=front["id"],
                title=front["title"],
                slug=front["slug"],
                kind=front["kind"],
                status=front["status"],
                affected=", ".join(front.get("affected") or []) or "none",
                fixed=front.get("fixed_in") or "not fixed",
                confidence=front["confidence"],
                verified=last_verified(front),
            )
        )
    return INDEX_HEADER + "\n".join(lines) + "\n"


def result_artifact_names(run_id, repository=None, run=subprocess.run):
    completed = run(
        ["gh", "api", f"repos/{repository or '{owner}/{repo}'}/actions/runs/{run_id}/artifacts",
         "--jq", ".artifacts[].name"],
        capture_output=True, text=True, check=True,
    )
    return [name for name in completed.stdout.split() if name.startswith(RESULT_ARTIFACT_PREFIX)]


def download_run(run_id, destination, repository=None, run=subprocess.run):
    if not result_artifact_names(run_id, repository, run):
        return
    command = ["gh", "run", "download", str(run_id), "--dir", str(destination), "--pattern", f"{RESULT_ARTIFACT_PREFIX}*"]
    if repository:
        command += ["--repo", repository]
    run(command, check=True)


def stamp(root, results, write_index=True):
    root = Path(root)
    images = json.loads((root / "harness" / "images.json").read_text(encoding="utf-8"))
    matched = [result for result in results if result["class"] == "match"]
    skipped = [result for result in results if result["class"] != "match"]
    by_slug = {}
    for result in matched:
        if result["tag"] not in images["tags"] or result["digest"] != images["tags"][result["tag"]]["digest"]:
            raise StampError(f"{result['slug']} {result['tag']}: digest is not the one pinned in images.json")
        verified_item(result)
        if not (root / "entries" / result["slug"] / "README.md").is_file():
            raise StampError(f"no entry named {result['slug']}")
        by_slug.setdefault(result["slug"], []).append(result)
    for slug, slug_results in sorted(by_slug.items()):
        stamp_entry(root / "entries" / slug, slug_results, images)
    if write_index:
        (root / "INDEX.md").write_text(render_index(entry_fronts(root / "entries")), encoding="utf-8")
    return sorted(by_slug), skipped


def build_parser():
    parser = argparse.ArgumentParser(description="Stamp CI repro results into entries and regenerate INDEX.md.")
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--run")
    source.add_argument("--results")
    source.add_argument("--index-only", action="store_true")
    parser.add_argument("--repo")
    parser.add_argument("--root", default=str(ROOT))
    return parser


def main(argv=None, download=download_run):
    args = build_parser().parse_args(argv)
    try:
        if args.index_only:
            stamped, skipped = stamp(args.root, [])
        elif args.results:
            stamped, skipped = stamp(args.root, load_results(args.results))
        else:
            with tempfile.TemporaryDirectory() as directory:
                download(args.run, directory, args.repo)
                stamped, skipped = stamp(args.root, load_results(directory))
    except (StampError, OSError, ValueError, KeyError, subprocess.CalledProcessError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    for slug in stamped:
        print(f"stamped {slug}")
    for result in skipped:
        print(f"not stamped: {result['slug']} {result['tag']} is {result['class']}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main())
